const createNextIntlPlugin = require("next-intl/plugin");
// Default convention path (./i18n/request.ts) — see that file's header
// comment for why it exists despite this app never calling useTranslations().
const withNextIntl = createNextIntlPlugin();

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  images: {
    // Product/brand placeholders are local SVGs in public/ (generated by
    // scripts/gen-placeholders.mjs) — no external image host needed for dev.
    // Add Cloudinary here in Phase 3, see plan §6.
    //
    // Those SVGs are rendered with `unoptimized` at each call site rather
    // than enabling `dangerouslyAllowSVG` here: there is nothing to optimise
    // in a vector, and the flag would also apply to any future remote image.
    remotePatterns: [
      // YouTube poster frames for the click-to-play video component (plan §6).
      { protocol: "https", hostname: "i.ytimg.com" },
      // Cloudinary-hosted brand/product images (Phase 6, real upload —
      // docs/CLOUDINARY-SETUP.md). Every account's delivery URL is
      // res.cloudinary.com/{cloud_name}/..., so this one pattern covers
      // any Cloudinary account, not just the one currently configured.
      { protocol: "https", hostname: "res.cloudinary.com" },
    ],
  },
};

module.exports = withNextIntl(nextConfig);
